# Readable prose spacing; identifiers and URLs remain untouched.
import re
def tidy(s):return re.sub(r'(?<=\d)(?=[A-Za-z])',' ',re.sub(r'(?<=[A-Za-z])(?=\d)',' ',s)).replace('ANC≥','ANC ≥').replace('WBC≥','WBC ≥').replace('DLCO<','DLCO <').replace('CrCl<','CrCl <').replace('CrCl>','CrCl >')
keys={'label','message','explanation','schedule_summary','duration_text','note','administration','mapping_basis','resolution','scope_note','document','section'}
def walk(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if isinstance(v,str) and k in keys:x[k]=tidy(v)
   else:walk(v)
 elif isinstance(x,list):
  for v in x:walk(v)
walk(p)
p['supportive_care']['other_supportive_care']=[tidy(s) for s in p['supportive_care']['other_supportive_care']]
for k in ['baseline','during','before_each_course']:p['monitoring'][k]=[tidy(s) for s in p['monitoring'][k]]
